1	package com.loja.checkout;
2	
3	import com.loja.checkout.api.PedidoRecusado;
4	import com.loja.checkout.api.ResumoRequest;
5	import com.loja.checkout.api.ResumoResponse;
6	import com.loja.checkout.clube.NivelClube;
7	import com.loja.checkout.cupom.ContextoCupom;
8	import com.loja.checkout.cupom.Cupom;
9	import com.loja.checkout.dominio.Catalogo;
10	import com.loja.checkout.dominio.Dinheiro;
11	import com.loja.checkout.dominio.ItemPedido;
12	import com.loja.checkout.dominio.Pedido;
13	import com.loja.checkout.dominio.Regiao;
14	import com.loja.checkout.entrega.Entrega;
15	import com.loja.checkout.entrega.ModalidadeEntrega;
16	import com.loja.checkout.pagamento.FormaPagamento;
17	import com.loja.checkout.pagamento.ResultadoPagamento;
18	import org.springframework.stereotype.Service;
19	
20	import java.math.BigDecimal;
21	import java.util.List;
22	import java.util.Optional;
23	
24	/**
25	 * Único lugar com a ordem das validações e a ordem do cálculo. Não conhece
26	 * modalidade, cupom, nível ou forma de pagamento nenhum: só as interfaces.
27	 */
28	@Service
29	public class CalculadoraResumo {
30	
31	    private final Catalogo<ModalidadeEntrega> entregas;
32	    private final Catalogo<Cupom> cupons;
33	    private final Catalogo<NivelClube> niveis;
34	    private final Catalogo<FormaPagamento> pagamentos;
35	
36	    CalculadoraResumo(Catalogo<ModalidadeEntrega> entregas,
37	                      Catalogo<Cupom> cupons,
38	                      Catalogo<NivelClube> niveis,
39	                      Catalogo<FormaPagamento> pagamentos) {
40	        this.entregas = entregas;
41	        this.cupons = cupons;
42	        this.niveis = niveis;
43	        this.pagamentos = pagamentos;
44	    }
45	
46	    public ResumoResponse calcular(ResumoRequest request) {
47	        Pedido pedido = pedidoValido(request);
48	        NivelClube nivel = niveis.buscar(request.nivelClube())
49	                .orElseThrow(() -> new PedidoRecusado("NIVEL_CLUBE_INVALIDO"));
50	        Regiao regiao = Regiao.porNome(request.regiao())
51	                .orElseThrow(() -> new PedidoRecusado("REGIAO_INVALIDA"));
52	        ModalidadeEntrega modalidade = entregas.buscar(request.modalidadeEntrega())
53	                .orElseThrow(() -> new PedidoRecusado("MODALIDADE_INVALIDA"));
54	        if (!modalidade.atende(pedido)) {
55	            throw new PedidoRecusado("MODALIDADE_INDISPONIVEL");
56	        }
57	
58	        BigDecimal subtotalProdutos = pedido.subtotal();
59	        Entrega entrega = modalidade.apurar(pedido);
60	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.ZERO : entrega.frete();
61	
62	        BigDecimal descontoCupom = descontoCupom(request.cupom(), new ContextoCupom(pedido, frete));
63	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
64	        BigDecimal totalPedido = Dinheiro.centavos(
65	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
66	
67	        FormaPagamento pagamento = pagamentos.buscar(request.formaPagamento())
68	                .orElseThrow(() -> new PedidoRecusado("FORMA_PAGAMENTO_INVALIDA"));
69	        int parcelas = request.parcelasOuUma();
70	        if (!pagamento.permiteParcelas(parcelas)) {
71	            throw new PedidoRecusado("PARCELAMENTO_INVALIDO");
72	        }
73	        if (!pagamento.atende(totalPedido)) {
74	            throw new PedidoRecusado("FORMA_PAGAMENTO_INDISPONIVEL");
75	        }
76	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
77	
78	        return new ResumoResponse(
79	                subtotalProdutos,
80	                descontoCupom,
81	                frete,
82	                entrega.prazoDias(),
83	                seguro,
84	                Dinheiro.centavos(resultado.totalFinal().subtract(totalPedido)),
85	                Dinheiro.centavos(resultado.totalFinal()),
86	                parcelas,
87	                Dinheiro.centavos(resultado.valorParcela()),
88	                nivel.credito(subtotalProdutos),
89	                nivel.brinde(subtotalProdutos));
90	    }
91	
92	    private BigDecimal descontoCupom(String codigo, ContextoCupom contexto) {
93	        if (codigo == null || codigo.isBlank()) {
94	            return Dinheiro.ZERO;
95	        }
96	        Cupom cupom = cupons.buscar(codigo).orElseThrow(() -> new PedidoRecusado("CUPOM_INVALIDO"));
97	        if (!cupom.aplicavel(contexto)) {
98	            throw new PedidoRecusado("CUPOM_NAO_APLICAVEL");
99	        }
100	        return cupom.desconto(contexto);
101	    }
102	
103	    private Pedido pedidoValido(ResumoRequest request) {
104	        List<ResumoRequest.ItemRequest> itens = request.itens();
105	        if (itens == null || itens.isEmpty() || itens.stream().anyMatch(this::itemInvalido)) {
106	            throw new PedidoRecusado("PEDIDO_INVALIDO");
107	        }
108	        return new Pedido(itens.stream()
109	                .map(item -> new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg()))
110	                .toList());
111	    }
112	
113	    private boolean itemInvalido(ResumoRequest.ItemRequest item) {
114	        return item == null
115	                || naoPositivo(item.precoUnitario())
116	                || item.quantidade() == null || item.quantidade() <= 0
117	                || naoPositivo(item.pesoKg());
118	    }
119	
120	    private boolean naoPositivo(BigDecimal valor) {
121	        return Optional.ofNullable(valor)
122	                .map(v -> v.compareTo(BigDecimal.ZERO) <= 0)
123	                .orElse(true);
124	    }
125	}
