1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.MathContext;
8	
9	/** Até 3x sem juros; de 4x a 12x com juros de 1,99% ao mês (tabela Price). */
10	@Component
11	class Cartao implements FormaPagamento {
12	
13	    private static final int PARCELAS_MAXIMAS = 12;
14	    private static final int PARCELAS_SEM_JUROS = 3;
15	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean permiteParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
25	    }
26	
27	    @Override
28	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
29	        if (parcelas <= PARCELAS_SEM_JUROS) {
30	            BigDecimal totalFinal = Dinheiro.centavos(totalPedido);
31	            BigDecimal parcela = Dinheiro.centavos(
32	                    totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
33	            return new ResultadoPagamento(totalFinal, parcela);
34	        }
35	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
36	        return new ResultadoPagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
37	    }
38	
39	    /** parcela = total × taxa ÷ (1 − (1 + taxa)^−parcelas) */
40	    private BigDecimal parcelaPrice(BigDecimal totalPedido, int parcelas) {
41	        MathContext mc = MathContext.DECIMAL128;
42	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, mc);
43	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, mc));
44	        return totalPedido.multiply(TAXA_MENSAL, mc).divide(divisor, mc);
45	    }
46	}
